require 'socket'
require 'thread'
require 'timeout'

module DistCache
  class ConnectionPool
    attr_reader :connections, :mutex, :shutdown_flag

    def initialize(hosts, pool_size: 4)
      @hosts = hosts
      @pool_size = pool_size
      @connections = {}
      @mutex = Mutex.new
      @shutdown_flag = false
      @drain_callbacks = []
      @health_checker = nil
      initialize_pools
    end

    def initialize_pools
      @hosts.each do |host|
        @connections[host] = ConnectionBucket.new(host, @pool_size)
      end
    end

    def get(key)
      node = select_node(key)
      conn = acquire_connection(node)
      return nil unless conn
      begin
        conn.request(:get, key)
      ensure
        release_connection(node, conn)
      end
    end

    def set(key, value, ttl: 300)
      node = select_node(key)
      conn = acquire_connection(node)
      return false unless conn
      begin
        conn.request(:set, key, value, ttl)
      ensure
        release_connection(node, conn)
      end
    end

    def graceful_shutdown(timeout_sec: 10)
      @mutex.synchronize do
        @shutdown_flag = true
      end
      drain_start = Time.now
      drain_connections(timeout_sec, drain_start)
      notify_drain_complete
    end

    def register_drain_callback(callback)
      @drain_callbacks << callback
    end

    def start_health_checker(interval: 5)
      @health_checker = Thread.new do
        loop do
          break if @shutdown_flag
          check_all_nodes
          sleep interval
        end
      end
    end

    private

    def select_node(key)
      hash = key.bytes.reduce(0) { |acc, b| (acc * 31 + b) & 0xFFFFFFFF }
      @hosts[hash % @hosts.length]
    end

    def acquire_connection(node)
      @mutex.synchronize do
        return nil if @shutdown_flag
      end
      bucket = @connections[node]
      bucket&.checkout
    end

    def release_connection(node, conn)
      bucket = @connections[node]
      should_close = @mutex.synchronize { @shutdown_flag }
      if should_close
        conn.close
      else
        bucket&.checkin(conn)
      end
    end

    def drain_connections(timeout_sec, start_time)
      @connections.each do |host, bucket|
        remaining = timeout_sec - (Time.now - start_time)
        break if remaining <= 0
        bucket.drain(remaining)
      end
    end

    def notify_drain_complete
      @drain_callbacks.each { |cb| cb.call(self) }
    end

    def check_all_nodes
      @mutex.synchronize do
        return if @shutdown_flag
      end
      @connections.each do |host, bucket|
        next if bucket.nil?
        bucket.health_check
      end
    end
  end

  class ConnectionBucket
    def initialize(host, size)
      @host = host
      @size = size
      @available = Queue.new
      @active_count = 0
      @mutex = Mutex.new
      @closed = false
      populate
    end

    def checkout
      return nil if @closed
      begin
        conn = @available.pop(true)
        if conn.alive?
          conn
        else
          @mutex.synchronize { @active_count -= 1 }
          reconnect_one
          retry_checkout
        end
      rescue ThreadError
        nil
      end
    end

    def checkin(conn)
      if @closed
        conn.close
      else
        @available.push(conn)
      end
    end

    def drain(timeout)
      @closed = true
      deadline = Time.now + timeout
      drained = []
      while Time.now < deadline
        begin
          conn = @available.pop(true)
          conn.close
          drained << conn
        rescue ThreadError
          break
        end
      end
      drained.length
    end

    def health_check
      return false if @closed
      temp_conn = CacheConnection.new(@host)
      result = temp_conn.ping
      temp_conn.close
      result
    rescue => e
      false
    end

    private

    def populate
      @size.times do
        conn = CacheConnection.new(@host)
        @available.push(conn)
        @mutex.synchronize { @active_count += 1 }
      end
    end

    def reconnect_one
      conn = CacheConnection.new(@host)
      @available.push(conn)
      @mutex.synchronize { @active_count += 1 }
    rescue => e
      nil
    end

    def retry_checkout
      begin
        @available.pop(true)
      rescue ThreadError
        nil
      end
    end
  end

  class CacheConnection
    attr_reader :socket, :host, :port

    def initialize(host_string)
      @host, port_str = host_string.split(':')
      @port = port_str.to_i
      @socket = nil
      @connected = false
      connect
    end

    def connect
      @socket = TCPSocket.new(@host, @port)
      @connected = true
    rescue => e
      @socket = nil
      @connected = false
    end

    def alive?
      @connected && @socket && !@socket.closed?
    end

    def request(cmd, *args)
      raise "Not connected" unless alive?
      payload = build_payload(cmd, args)
      @socket.write(payload)
      read_response
    end

    def ping
      return false unless alive?
      @socket.write("PING\r\n")
      response = @socket.gets
      response&.strip == "PONG"
    end

    def close
      @socket&.close unless @socket&.closed?
      @connected = false
      @socket = nil
    end

    private

    def sanitize_arg(value)
      str = value.to_s
      # Prevent protocol/CRLF injection: reject arguments containing
      # carriage returns, newlines, or NUL bytes that could be used to
      # inject additional cache protocol commands.
      if str.match?(/[\r\n\x00]/)
        raise ArgumentError, "Invalid characters in argument (CR/LF/NUL not allowed)"
      end
      str
    end

    def build_payload(cmd, args)
      cmd_str = sanitize_arg(cmd.to_s.upcase)
      parts = [cmd_str] + args.map { |a| sanitize_arg(a) }
      parts.join(' ') + "\r\n"
    end

    def read_response
      line = @socket.gets
      return nil if line.nil?
      parse_response(line.strip)
    end

    def parse_response(line)
      case line[0]
      when '+' then line[1..]
      when '-' then raise "CacheError: #{line[1..]}"
      when '$'
        len = line[1..].to_i
        return nil if len == -1
        return nil if len < 0
        data = @socket.read(len + 2)
        return nil if data.nil?
        data[0...len]
      else
        line
      end
    end
  end

  class Client
    def initialize(hosts)
      @pool = ConnectionPool.new(hosts)
      @shutting_down = false
      setup_signal_handlers
    end

    def get(key)
      return nil if @shutting_down
      @pool.get(key)
    end

    def set(key, value, ttl: 300)
      return false if @shutting_down
      @pool.set(key, value, ttl: ttl)
    end

    def shutdown
      @shutting_down = true
      @pool.graceful_shutdown
    end

    private

    def setup_signal_handlers
      Signal.trap('TERM') { shutdown }
      Signal.trap('INT') { shutdown }
    end
  end
end
